toolScript:
// --- Setup ---
        const canvas = document.getElementById('test-canvas');
        const ctx = canvas.getContext('2d');
        let speed = 8; // Pixels per frame
        let animationId;
        // Stats
        let lastTime = performance.now();
        let frameCount = 0;
        let lastFpsTime = lastTime;
        let fps = 0;
        let hz = 0;
        // UFO Asset (Base64 SVG for performance/portability)
        const ufoImg = new Image();
        ufoImg.src = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%2339ff14'%3E%3Cpath d='M12 2a5 5 0 0 0-5 5v1H4a2 2 0 0 0-2 2v2a3 3 0 0 0 3 3h14a3 3 0 0 0 3-3v-2a2 2 0 0 0-2-2h-3V7a5 5 0 0 0-5-5zm0 2a3 3 0 0 1 3 3v1H9V7a3 3 0 0 1 3-3zm-9 8v-1h18v1a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z'/%3E%3C/svg%3E";
        // Positions for 3 lanes
        let lanes = [
            { y: 50, x: 0, scale: 1.0, label: "Current Logic Clock" },
            { y: 150, x: 0, scale: 1.0, label: "50% Persistence Path" },
            { y: 250, x: 0, scale: 1.0, label: "25% Persistence Path" }
        ];
        function resize() {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }
        window.addEventListener('resize', resize);
        resize();
        // --- Core Loop ---
        function loop(timestamp) {
            // FPS Calc
            frameCount++;
            if (timestamp - lastFpsTime >= 1000) {
                fps = frameCount;
                frameCount = 0;
                lastFpsTime = timestamp;
                updateHUD(fps);
            }
            // Clear Frame
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Draw Background Grids (Vertical lines to track blur)
            ctx.strokeStyle = "rgba(255,255,255,0.05)";
            ctx.lineWidth = 1;
            for (let i = 0; i < canvas.width; i += 100) {
                ctx.beginPath();
                ctx.moveTo(i, 0);
                ctx.lineTo(i, canvas.height);
                ctx.stroke();
            }
            // Draw Lanes
            ctx.fillStyle = "rgba(255,255,255,0.1)";
            lanes.forEach(lane => {
                ctx.fillRect(0, lane.y + 40, canvas.width, 2); // Guide line
            });
            // Update & Draw UFOs
            lanes.forEach((lane, index) => {
                // Determine speed for this lane
                let currentSpeed = speed;
                if (index === 1) currentSpeed = speed / 2;
                if (index === 2) currentSpeed = speed / 4;
                // Move logic
                lane.x = (lane.x + currentSpeed) % (canvas.width + 64);
                // Spaced intervals
                const spacing = 300; // px
                for (let i = -1; i < (canvas.width / spacing) + 1; i++) {
                    const drawX = (lane.x + (i * spacing)) % (canvas.width + 100) - 50;
                    ctx.drawImage(ufoImg, drawX, lane.y, 48, 48);
                }
                // Draw Meta Label
                ctx.fillStyle = "#64748b";
                ctx.font = "bold 9px 'JetBrains Mono'";
                ctx.fillText(`${lane.label.toUpperCase()} [${(currentSpeed * 60).toFixed(0)} PX/SEC]`, 20, lane.y + 65);
            });
            animationId = requestAnimationFrame(loop);
        }
        // --- HUD Logic ---
        function updateHUD(currentFps) {
            document.getElementById('display-fps').innerText = currentFps;
            // Heuristic Hz Estimation
            let estimatedHz = Math.round(currentFps / 5) * 5;
            if (currentFps > 55 && currentFps < 65) estimatedHz = 60;
            if (currentFps > 135 && currentFps < 155) estimatedHz = 144;
            if (currentFps > 230 && currentFps < 250) estimatedHz = 240;
            document.getElementById('display-hz').innerText = estimatedHz;
            document.getElementById('side-hz').innerText = estimatedHz + " Hz";
            const status = document.getElementById('sync-status');
            const diff = Math.abs(currentFps - estimatedHz);
            if (diff <= 3 && currentFps > 30) {
                status.innerText = "VSYNC ACTIVE";
                status.className = "text-sm font-black status-valid uppercase tracking-widest";
                document.getElementById('side-vsync').innerText = "STABLE";
            } else {
                status.innerText = "FRAME DROP DETECTED";
                status.className = "text-sm font-black status-invalid uppercase tracking-widest";
                document.getElementById('side-vsync').innerText = "UNSTABLE";
            }
        }
        // --- Controls ---
        function setSpeed(val) {
            speed = val;
            document.querySelectorAll('#spd-4, #spd-8, #spd-16, #spd-32').forEach(b => b.classList.remove('active'));
            document.getElementById(`spd-${val}`).classList.add('active');
        }
        function setBg(color) {
            document.getElementById('test-canvas').style.backgroundColor = color;
            document.querySelectorAll('#bg-dark, #bg-gray, #bg-light').forEach(b => b.classList.remove('active'));
            if (color === '#0f172a') document.getElementById('bg-dark').classList.add('active');
            if (color === '#475569') document.getElementById('bg-gray').classList.add('active');
            if (color === '#f8fafc') document.getElementById('bg-light').classList.add('active');
        }
        // Fullscreen Toggle
        canvas.addEventListener('dblclick', () => {
            if (!document.fullscreenElement) {
                canvas.requestFullscreen().catch(err => {
                    console.log("Fullscreen inhibited.");
                });
            } else {
                document.exitFullscreen();
            }
        });
        // Initialize Loop
        ufoImg.onload = () => {
            animationId = requestAnimationFrame(loop);
        };
        // Scroll Logic
